      "Defaulted": "package showcase.customtypes\n\nimport dev.typr.foundations.DbText\nimport dev.typr.foundations.PgText\n\n/** This signals a value where if you don't provide it, postgres will generate it for you */\nsealed trait Defaulted[T] {\n  def fold[U](\n    onDefault: => U,\n    onProvided: T => U\n  ): U\n\n  def getOrElse(onDefault: => T): T\n\n  def visit(\n    onDefault: => Unit,\n    onProvided: T => Unit\n  ): Unit\n}\n\nobject Defaulted {\n  given pgText[T](using t: DbText[T]): PgText[Defaulted[T]] = PgText.instance((ot, sb) => ot.visit({ sb.append(\"__DEFAULT_VALUE__\"): @scala.annotation.nowarn }, value => t.unsafeEncode(value, sb)))\n\n  case class Provided[T](value: T) extends Defaulted[T] {\n    override def fold[U](\n      onDefault: => U,\n      onProvided: T => U\n    ): U = onProvided(value)\n\n    override def getOrElse(onDefault: => T): T = value\n\n    override def visit(\n      onDefault: => Unit,\n      onProvided: T => Unit\n    ): Unit = onProvided(value)\n  }\n\n  case class UseDefault[T]() extends Defaulted[T] {\n    override def fold[U](\n      onDefault: => U,\n      onProvided: T => U\n    ): U = onDefault\n\n    override def getOrElse(onDefault: => T): T = onDefault\n\n    override def visit(\n      onDefault: => Unit,\n      onProvided: T => Unit\n    ): Unit = onDefault\n  }\n}",
