      "EmployeeRepoMock": "package showcase.showcase.employee;\n\nimport dev.typr.foundations.dsl.DeleteBuilder;\nimport dev.typr.foundations.dsl.DeleteBuilderMock;\nimport dev.typr.foundations.dsl.DeleteParams;\nimport dev.typr.foundations.dsl.SelectBuilder;\nimport dev.typr.foundations.dsl.SelectBuilderMock;\nimport dev.typr.foundations.dsl.SelectParams;\nimport dev.typr.foundations.dsl.UpdateBuilder;\nimport dev.typr.foundations.dsl.UpdateBuilderMock;\nimport dev.typr.foundations.dsl.UpdateParams;\nimport java.lang.RuntimeException;\nimport java.sql.Connection;\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.Iterator;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.function.Function;\nimport java.util.stream.Collectors;\n\npublic record EmployeeRepoMock(\n  java.util.function.Function<EmployeeRowUnsaved, EmployeeRow> toRow,\n  HashMap<EmployeeId, EmployeeRow> map\n) implements EmployeeRepo {\n  public EmployeeRepoMock(java.util.function.Function<EmployeeRowUnsaved, EmployeeRow> toRow) {\n    this(toRow, new HashMap<EmployeeId, EmployeeRow>());\n  };\n\n  public EmployeeRepoMock withToRow(java.util.function.Function<EmployeeRowUnsaved, EmployeeRow> toRow) {\n    return new EmployeeRepoMock(toRow, map);\n  };\n\n  public EmployeeRepoMock withMap(HashMap<EmployeeId, EmployeeRow> map) {\n    return new EmployeeRepoMock(toRow, map);\n  };\n\n  @Override\n  public DeleteBuilder<EmployeeFields, EmployeeRow> delete() {\n    return new DeleteBuilderMock<>(EmployeeFields.structure(), () -> new ArrayList<>(map.values()), DeleteParams.empty(), row -> row.id(), id -> map.remove(id));\n  };\n\n  @Override\n  public Boolean deleteById(\n    EmployeeId id,\n    Connection c\n  ) {\n    return Optional.ofNullable(map.remove(id)).isPresent();\n  };\n\n  @Override\n  public Integer deleteByIds(\n    EmployeeId[] ids,\n    Connection c\n  ) {\n    var count = 0;\n    for (var id : ids) {\n      if (Optional.ofNullable(map.remove(id)).isPresent()) {\n      count = count + 1;;\n    };\n    };\n    return count;\n  };\n\n  @Override\n  public EmployeeRow insert(\n    EmployeeRow unsaved,\n    Connection c\n  ) {\n    if (map.containsKey(unsaved.id())) {\n      throw new RuntimeException(\"id \" + unsaved.id() + \" already exists\");\n    };\n    map.put(unsaved.id(), unsaved);\n    return unsaved;\n  };\n\n  @Override\n  public EmployeeRow insert(\n    EmployeeRowUnsaved unsaved,\n    Connection c\n  ) {\n    return insert(toRow.apply(unsaved), c);\n  };\n\n  @Override\n  public SelectBuilder<EmployeeFields, EmployeeRow> select() {\n    return new SelectBuilderMock<>(EmployeeFields.structure(), () -> new ArrayList<>(map.values()), SelectParams.empty());\n  };\n\n  @Override\n  public List<EmployeeRow> selectAll(Connection c) {\n    return new ArrayList<>(map.values());\n  };\n\n  @Override\n  public Optional<EmployeeRow> selectById(\n    EmployeeId id,\n    Connection c\n  ) {\n    return Optional.ofNullable(map.get(id));\n  };\n\n  @Override\n  public List<EmployeeRow> selectByIds(\n    EmployeeId[] ids,\n    Connection c\n  ) {\n    var result = new ArrayList<EmployeeRow>();\n    for (var id : ids) {\n      var opt = Optional.ofNullable(map.get(id));\n      if (opt.isPresent()) {\n      result.add(opt.get());\n    };\n    };\n    return result;\n  };\n\n  @Override\n  public Map<EmployeeId, EmployeeRow> selectByIdsTracked(\n    EmployeeId[] ids,\n    Connection c\n  ) {\n    return selectByIds(ids, c).stream().collect(Collectors.toMap((EmployeeRow row) -> row.id(), Function.identity()));\n  };\n\n  @Override\n  public Optional<EmployeeRow> selectByUniqueEmail(\n    String email,\n    Connection c\n  ) {\n    return new ArrayList<>(map.values()).stream().filter(v -> email.equals(v.email())).findFirst();\n  };\n\n  @Override\n  public UpdateBuilder<EmployeeFields, EmployeeRow> update() {\n    return new UpdateBuilderMock<>(EmployeeFields.structure(), () -> new ArrayList<>(map.values()), UpdateParams.empty(), row -> row);\n  };\n\n  @Override\n  public Boolean update(\n    EmployeeRow row,\n    Connection c\n  ) {\n    var shouldUpdate = Optional.ofNullable(map.get(row.id())).filter(oldRow -> !oldRow.equals(row)).isPresent();\n    if (shouldUpdate) {\n      map.put(row.id(), row);;\n    };\n    return shouldUpdate;\n  };\n\n  @Override\n  public EmployeeRow upsert(\n    EmployeeRow unsaved,\n    Connection c\n  ) {\n    map.put(unsaved.id(), unsaved);\n    return unsaved;\n  };\n\n  @Override\n  public List<EmployeeRow> upsertBatch(\n    Iterator<EmployeeRow> unsaved,\n    Connection c\n  ) {\n    var result = new ArrayList<EmployeeRow>();\n    while (unsaved.hasNext()) {\n      var row = unsaved.next();\n      map.put(row.id(), row);\n      result.add(row);\n    };\n    return result;\n  };\n}",
