      "EmployeeRepoMock": "package showcase.showcase.employee\n\nimport dev.typr.foundations.kotlin.DeleteBuilder\nimport dev.typr.foundations.kotlin.DeleteBuilderMock\nimport dev.typr.foundations.kotlin.DeleteParams\nimport dev.typr.foundations.kotlin.SelectBuilder\nimport dev.typr.foundations.kotlin.SelectBuilderMock\nimport dev.typr.foundations.kotlin.SelectParams\nimport dev.typr.foundations.kotlin.UpdateBuilder\nimport dev.typr.foundations.kotlin.UpdateBuilderMock\nimport dev.typr.foundations.kotlin.UpdateParams\nimport java.lang.RuntimeException\nimport java.sql.Connection\nimport java.util.ArrayList\nimport kotlin.collections.Iterator\nimport kotlin.collections.List\nimport kotlin.collections.Map\nimport kotlin.collections.MutableMap\n\ndata class EmployeeRepoMock(\n  val toRow: (EmployeeRowUnsaved) -> EmployeeRow,\n  val map: MutableMap<EmployeeId, EmployeeRow> = mutableMapOf<EmployeeId, EmployeeRow>()\n) : EmployeeRepo {\n  override fun delete(): DeleteBuilder<EmployeeFields, EmployeeRow> = DeleteBuilderMock(EmployeeFields.structure, { map.values.toList() }, DeleteParams.empty(), { row -> row.id }, { id -> map.remove(id) })\n\n  override fun deleteById(\n    id: EmployeeId,\n    c: Connection\n  ): Boolean = map.remove(id) != null\n\n  override fun deleteByIds(\n    ids: Array<EmployeeId>,\n    c: Connection\n  ): Int {\n    var count = 0\n    for (id in ids) {\n      if (map.remove(id) != null) {\n      count = count + 1\n    }\n    }\n    return count\n  }\n\n  override fun insert(\n    unsaved: EmployeeRow,\n    c: Connection\n  ): EmployeeRow {\n    if (map.containsKey(unsaved.id)) {\n      throw RuntimeException(\"id \" + unsaved.id + \" already exists\")\n    }\n    map[unsaved.id] = unsaved\n    return unsaved\n  }\n\n  override fun insert(\n    unsaved: EmployeeRowUnsaved,\n    c: Connection\n  ): EmployeeRow = insert(toRow(unsaved), c)\n\n  override fun select(): SelectBuilder<EmployeeFields, EmployeeRow> = SelectBuilderMock(EmployeeFields.structure, { map.values.toList() }, SelectParams.empty())\n\n  override fun selectAll(c: Connection): List<EmployeeRow> = map.values.toList()\n\n  override fun selectById(\n    id: EmployeeId,\n    c: Connection\n  ): EmployeeRow? = map[id]\n\n  override fun selectByIds(\n    ids: Array<EmployeeId>,\n    c: Connection\n  ): List<EmployeeRow> {\n    val result = ArrayList<EmployeeRow>()\n    for (id in ids) {\n      val opt = map[id]\n      if (opt != null) {\n      result.add(opt!!)\n    }\n    }\n    return result\n  }\n\n  override fun selectByIdsTracked(\n    ids: Array<EmployeeId>,\n    c: Connection\n  ): Map<EmployeeId, EmployeeRow> = selectByIds(ids, c).associateBy({ row: EmployeeRow -> row.id })\n\n  override fun selectByUniqueEmail(\n    email: String,\n    c: Connection\n  ): EmployeeRow? = map.values.toList().find({ v -> (email == v.email) })\n\n  override fun update(): UpdateBuilder<EmployeeFields, EmployeeRow> = UpdateBuilderMock(EmployeeFields.structure, { map.values.toList() }, UpdateParams.empty(), { row -> row })\n\n  override fun update(\n    row: EmployeeRow,\n    c: Connection\n  ): Boolean {\n    val shouldUpdate = map[row.id]?.takeIf({ oldRow -> (oldRow != row) }) != null\n    if (shouldUpdate) {\n      map[row.id] = row\n    }\n    return shouldUpdate\n  }\n\n  override fun upsert(\n    unsaved: EmployeeRow,\n    c: Connection\n  ): EmployeeRow {\n    map[unsaved.id] = unsaved\n    return unsaved\n  }\n\n  override fun upsertBatch(\n    unsaved: Iterator<EmployeeRow>,\n    c: Connection\n  ): List<EmployeeRow> {\n    val result = ArrayList<EmployeeRow>()\n    while (unsaved.hasNext()) {\n      val row = unsaved.next()\n      map[row.id] = row\n      result.add(row)\n    }\n    return result\n  }\n}",
