      "ProjectAssignmentRowUnsaved": "package showcase.showcase.project_assignment\n\nimport java.time.LocalDate\nimport showcase.customtypes.Defaulted\nimport showcase.customtypes.Defaulted.UseDefault\nimport showcase.showcase.employee.EmployeeId\nimport showcase.showcase.project.ProjectId\n\n/** This class corresponds to a row in table `showcase.project_assignment` which has not been persisted yet */\ndata class ProjectAssignmentRowUnsaved(\n  /** Points to [showcase.showcase.employee.EmployeeRow.id] */\n  val employeeId: EmployeeId,\n  /** Points to [showcase.showcase.project.ProjectRow.id] */\n  val projectId: ProjectId,\n  val role: String,\n  val startDate: LocalDate? = null,\n  val endDate: LocalDate? = null,\n  /** Default: 0 */\n  val hoursAllocated: Defaulted<Int?> = UseDefault()\n) {\n  fun toRow(hoursAllocatedDefault: () -> Int?): ProjectAssignmentRow = ProjectAssignmentRow(employeeId = employeeId, projectId = projectId, role = role, hoursAllocated = hoursAllocated.getOrElse(hoursAllocatedDefault), startDate = startDate, endDate = endDate)\n}",
