      "ProjectRow": "package showcase.showcase.project\n\nimport dev.typr.foundations.DuckDbTypes\nimport dev.typr.foundations.data.Json\nimport dev.typr.foundations.kotlin.RowParser\nimport dev.typr.foundations.kotlin.RowParsers\nimport dev.typr.foundations.kotlin.nullable\nimport java.math.BigDecimal\nimport java.time.Duration\nimport java.time.LocalDate\nimport java.time.LocalDateTime\nimport showcase.ProjectProjectPhases\nimport showcase.customtypes.Defaulted\n\n/** Table: showcase.project\n  * Primary key: id\n  */\ndata class ProjectRow(\n  val id: ProjectId,\n  val name: String,\n  val description: String?,\n  val startDate: LocalDate?,\n  val endDate: LocalDate?,\n  val budget: BigDecimal?,\n  /** Default: 'planning' */\n  val status: String?,\n  /** Default: CURRENT_TIMESTAMP */\n  val createdAt: LocalDateTime?,\n  val milestones: Array<String>?,\n  val budgetSnapshots: Array<BigDecimal>?,\n  val teamMembers: Array<String>?,\n  val projectPhases: ProjectProjectPhases?,\n  val config: /* MAP type - mapped to String */ String?,\n  val riskScores: /* MAP type - mapped to String */ String?,\n  val estimatedDuration: Duration?,\n  val actualDuration: Duration?,\n  val metadata: Json?\n) {\n  fun toUnsavedRow(\n    status: Defaulted<String?>,\n    createdAt: Defaulted<LocalDateTime?>\n  ): ProjectRowUnsaved = ProjectRowUnsaved(id, name, description, startDate, endDate, budget, milestones, budgetSnapshots, teamMembers, projectPhases, config, riskScores, estimatedDuration, actualDuration, metadata, status, createdAt)\n\n  companion object {\n    val _rowParser: RowParser<ProjectRow> = RowParsers.of(ProjectId.duckDbType, DuckDbTypes.varchar, DuckDbTypes.varchar.nullable(), DuckDbTypes.date.nullable(), DuckDbTypes.date.nullable(), DuckDbTypes.numeric.nullable(), DuckDbTypes.varchar.nullable(), DuckDbTypes.timestamp.nullable(), DuckDbTypes.varcharArray.nullable(), DuckDbTypes.decimalArray.nullable(), DuckDbTypes.varcharArray.nullable(), ProjectProjectPhases.duckDbType.nullable(), DuckDbTypes.varchar.mapTo(DuckDbTypes.varchar).nullable(), DuckDbTypes.varchar.mapTo(DuckDbTypes.integer).nullable(), DuckDbTypes.interval.nullable(), DuckDbTypes.interval.nullable(), DuckDbTypes.json.nullable(), { t0, t1, t2, t3, t4, t5, t6, t7, t8, t9, t10, t11, t12, t13, t14, t15, t16 -> ProjectRow(t0, t1, t2, t3, t4, t5, t6, t7, t8, t9, t10, t11, t12, t13, t14, t15, t16) }, { row -> arrayOf<Any?>(row.id, row.name, row.description, row.startDate, row.endDate, row.budget, row.status, row.createdAt, row.milestones, row.budgetSnapshots, row.teamMembers, row.projectPhases, row.config, row.riskScores, row.estimatedDuration, row.actualDuration, row.metadata) })\n  }\n}",
      "ProjectId": "package showcase.showcase.project\n\nimport dev.typr.foundations.DuckDbType\nimport dev.typr.foundations.DuckDbTypes\nimport dev.typr.foundations.internal.arrayMap\nimport dev.typr.foundations.kotlin.Bijection\n\n/** Type for the primary key of table `showcase.project` */\ndata class ProjectId(val value: String) {\n  override fun toString(): kotlin.String {\n    return value.toString()\n  }\n\n  companion object {\n    val bijection: Bijection<ProjectId, String> =\n      Bijection.of(ProjectId::value, ::ProjectId)\n\n    val duckDbType: DuckDbType<ProjectId> =\n      DuckDbTypes.varchar.bimap(::ProjectId, ProjectId::value)\n\n    val pgTypeArray: DuckDbType<Array<ProjectId>> =\n      DuckDbTypes.varcharArray.bimap({ xs -> arrayMap.map(xs, ::ProjectId, ProjectId::class.java) }, { xs -> arrayMap.map(xs, ProjectId::value, String::class.java) })\n  }\n}",
