      "OrderItemRow": "package showcase.showcase.order_item\n\nimport dev.typr.foundations.DuckDbTypes\nimport dev.typr.foundations.kotlin.KotlinDbTypes\nimport dev.typr.foundations.kotlin.RowParser\nimport dev.typr.foundations.kotlin.RowParsers\nimport dev.typr.foundations.kotlin.nullable\nimport java.math.BigDecimal\nimport showcase.customtypes.Defaulted\nimport showcase.showcase.customer_order.CustomerOrderId\nimport showcase.showcase.product.ProductId\n\n/** Table: showcase.order_item\n  * Composite primary key: order_id, product_id\n  */\ndata class OrderItemRow(\n  /** Points to [showcase.showcase.customer_order.CustomerOrderRow.id] */\n  val orderId: CustomerOrderId,\n  /** Points to [showcase.showcase.product.ProductRow.id] */\n  val productId: ProductId,\n  val quantity: Int,\n  val unitPrice: BigDecimal,\n  /** Default: 0 */\n  val discount: BigDecimal?\n) {\n  fun compositeId(): OrderItemId = OrderItemId(orderId, productId)\n\n  fun id(): OrderItemId = this.compositeId()\n\n  fun toUnsavedRow(discount: Defaulted<BigDecimal?>): OrderItemRowUnsaved = OrderItemRowUnsaved(orderId, productId, quantity, unitPrice, discount)\n\n  companion object {\n    val _rowParser: RowParser<OrderItemRow> = RowParsers.of(CustomerOrderId.duckDbType, ProductId.duckDbType, KotlinDbTypes.DuckDbTypes.integer, DuckDbTypes.numeric, DuckDbTypes.numeric.nullable(), { t0, t1, t2, t3, t4 -> OrderItemRow(t0, t1, t2, t3, t4) }, { row -> arrayOf<Any?>(row.orderId, row.productId, row.quantity, row.unitPrice, row.discount) })\n\n    fun apply(\n      compositeId: OrderItemId,\n      quantity: Int,\n      unitPrice: BigDecimal,\n      discount: BigDecimal?\n    ): OrderItemRow = OrderItemRow(compositeId.orderId, compositeId.productId, quantity, unitPrice, discount)\n  }\n}",
      "OrderItemId": "package showcase.showcase.order_item\n\nimport dev.typr.foundations.kotlin.RowParser\nimport dev.typr.foundations.kotlin.RowParsers\nimport showcase.showcase.customer_order.CustomerOrderId\nimport showcase.showcase.product.ProductId\n\n/** Type for the composite primary key of table `showcase.order_item` */\ndata class OrderItemId(\n  val orderId: CustomerOrderId,\n  val productId: ProductId\n) {\n  companion object {\n    val _rowParser: RowParser<OrderItemId> = RowParsers.of(CustomerOrderId.duckDbType, ProductId.duckDbType, { t0, t1 -> OrderItemId(t0, t1) }, { row -> arrayOf<Any?>(row.orderId, row.productId) })\n  }\n}",
      "ProductRow": "package showcase.showcase.product\n\nimport dev.typr.foundations.DuckDbTypes\nimport dev.typr.foundations.data.Json\nimport dev.typr.foundations.kotlin.KotlinDbTypes\nimport dev.typr.foundations.kotlin.RowParser\nimport dev.typr.foundations.kotlin.RowParsers\nimport dev.typr.foundations.kotlin.nullable\nimport java.math.BigDecimal\nimport java.time.LocalDateTime\nimport showcase.ProductDimensions\nimport showcase.customtypes.Defaulted\nimport showcase.showcase.category.CategoryId\n\n/** Table: showcase.product\n  * Primary key: id\n  */\ndata class ProductRow(\n  val id: ProductId,\n  /** Points to [showcase.showcase.category.CategoryRow.id] */\n  val categoryId: CategoryId?,\n  val name: String,\n  val sku: String,\n  val price: BigDecimal,\n  val cost: BigDecimal?,\n  /** Default: true */\n  val inStock: Boolean?,\n  /** Default: 0 */\n  val quantity: Int?,\n  val weight: BigDecimal?,\n  /** Default: CURRENT_TIMESTAMP */\n  val createdAt: LocalDateTime?,\n  val tags: Array<String>?,\n  val images: Array<String>?,\n  val relatedSkus: Array<String>?,\n  val priceHistory: Array<BigDecimal>?,\n  val categoryIds: Array<Int>?,\n  val dimensions: ProductDimensions?,\n  val attributes: /* MAP type - mapped to String */ String?,\n  val specifications: /* MAP type - mapped to String */ String?,\n  val pricesByRegion: /* MAP type - mapped to String */ String?,\n  val stockByWarehouse: /* MAP type - mapped to String */ String?,\n  val seoMetadata: Json?\n) {\n  fun toUnsavedRow(\n    inStock: Defaulted<Boolean?>,\n    quantity: Defaulted<Int?>,\n    createdAt: Defaulted<LocalDateTime?>\n  ): ProductRowUnsaved = ProductRowUnsaved(id, categoryId, name, sku, price, cost, weight, tags, images, relatedSkus, priceHistory, categoryIds, dimensions, attributes, specifications, pricesByRegion, stockByWarehouse, seoMetadata, inStock, quantity, createdAt)\n\n  companion object {\n    val _rowParser: RowParser<ProductRow> = RowParsers.of(ProductId.duckDbType, CategoryId.duckDbType.nullable(), DuckDbTypes.varchar, DuckDbTypes.varchar, DuckDbTypes.numeric, DuckDbTypes.numeric.nullable(), KotlinDbTypes.DuckDbTypes.boolean_.nullable(), KotlinDbTypes.DuckDbTypes.integer.nullable(), DuckDbTypes.numeric.nullable(), DuckDbTypes.timestamp.nullable(), DuckDbTypes.varcharArray.nullable(), DuckDbTypes.varcharArray.nullable(), DuckDbTypes.varcharArray.nullable(), DuckDbTypes.decimalArray.nullable(), DuckDbTypes.integerArray.nullable(), ProductDimensions.duckDbType.nullable(), DuckDbTypes.varchar.mapTo(DuckDbTypes.varchar).nullable(), DuckDbTypes.varchar.mapTo(DuckDbTypes.varchar).nullable(), DuckDbTypes.varchar.mapTo(DuckDbTypes.numeric).nullable(), DuckDbTypes.varchar.mapTo(DuckDbTypes.integer).nullable(), DuckDbTypes.json.nullable(), { t0, t1, t2, t3, t4, t5, t6, t7, t8, t9, t10, t11, t12, t13, t14, t15, t16, t17, t18, t19, t20 -> ProductRow(t0, t1, t2, t3, t4, t5, t6, t7, t8, t9, t10, t11, t12, t13, t14, t15, t16, t17, t18, t19, t20) }, { row -> arrayOf<Any?>(row.id, row.categoryId, row.name, row.sku, row.price, row.cost, row.inStock, row.quantity, row.weight, row.createdAt, row.tags, row.images, row.relatedSkus, row.priceHistory, row.categoryIds, row.dimensions, row.attributes, row.specifications, row.pricesByRegion, row.stockByWarehouse, row.seoMetadata) })\n  }\n}",
      "ProductId": "package showcase.showcase.product\n\nimport dev.typr.foundations.DuckDbType\nimport dev.typr.foundations.DuckDbTypes\nimport dev.typr.foundations.internal.arrayMap\nimport dev.typr.foundations.kotlin.Bijection\n\n/** Type for the primary key of table `showcase.product` */\ndata class ProductId(val value: String) {\n  override fun toString(): kotlin.String {\n    return value.toString()\n  }\n\n  companion object {\n    val bijection: Bijection<ProductId, String> =\n      Bijection.of(ProductId::value, ::ProductId)\n\n    val duckDbType: DuckDbType<ProductId> =\n      DuckDbTypes.varchar.bimap(::ProductId, ProductId::value)\n\n    val pgTypeArray: DuckDbType<Array<ProductId>> =\n      DuckDbTypes.varcharArray.bimap({ xs -> arrayMap.map(xs, ::ProductId, ProductId::class.java) }, { xs -> arrayMap.map(xs, ProductId::value, String::class.java) })\n  }\n}",
