      "CustomerOrderRow": "package showcase.showcase.customer_order\n\nimport dev.typr.foundations.DuckDbTypes\nimport dev.typr.foundations.scala.DbTypeOps\nimport dev.typr.foundations.scala.RowParser\nimport dev.typr.foundations.scala.RowParsers\nimport dev.typr.foundations.scala.ScalaDbTypes\nimport java.time.Duration\nimport java.time.LocalDateTime\nimport java.time.OffsetDateTime\nimport showcase.CustomerOrderLineItemsSummary\nimport showcase.customtypes.Defaulted\nimport showcase.showcase.address.AddressId\nimport showcase.showcase.customer.CustomerId\n\n/** Table: showcase.customer_order\n * Primary key: id\n */\ncase class CustomerOrderRow(\n  id: CustomerOrderId,\n  /** Points to [[showcase.showcase.customer.CustomerRow.id]] */\n  customerId: CustomerId,\n  /** Points to [[showcase.showcase.address.AddressRow.id]] */\n  shippingAddressId: Option[AddressId],\n  /** Points to [[showcase.showcase.address.AddressRow.id]] */\n  billingAddressId: Option[AddressId],\n  /** Default: 'pending' */\n  status: Option[String],\n  subtotal: BigDecimal,\n  /** Default: 0 */\n  tax: Option[BigDecimal],\n  /** Default: 0 */\n  shipping: Option[BigDecimal],\n  total: BigDecimal,\n  notes: Option[String],\n  /** Default: CURRENT_TIMESTAMP */\n  createdAt: Option[LocalDateTime],\n  shippedAt: Option[LocalDateTime],\n  deliveredAt: Option[LocalDateTime],\n  /** Default: now() */\n  orderedAtTz: Option[OffsetDateTime],\n  deliveredAtTz: Option[OffsetDateTime],\n  tags: Option[Array[String]],\n  fulfillmentTimes: Option[Array[LocalDateTime]],\n  lineItemsSummary: Option[CustomerOrderLineItemsSummary],\n  metadata: Option[/* MAP type - mapped to String */ String],\n  processingTime: Option[Duration]\n) {\n  def toUnsavedRow(\n    status: Defaulted[Option[String]] = Defaulted.Provided(this.status),\n    tax: Defaulted[Option[BigDecimal]] = Defaulted.Provided(this.tax),\n    shipping: Defaulted[Option[BigDecimal]] = Defaulted.Provided(this.shipping),\n    createdAt: Defaulted[Option[LocalDateTime]] = Defaulted.Provided(this.createdAt),\n    orderedAtTz: Defaulted[Option[OffsetDateTime]] = Defaulted.Provided(this.orderedAtTz)\n  ): CustomerOrderRowUnsaved = {\n    new CustomerOrderRowUnsaved(\n      id,\n      customerId,\n      shippingAddressId,\n      billingAddressId,\n      subtotal,\n      total,\n      notes,\n      shippedAt,\n      deliveredAt,\n      deliveredAtTz,\n      tags,\n      fulfillmentTimes,\n      lineItemsSummary,\n      metadata,\n      processingTime,\n      status,\n      tax,\n      shipping,\n      createdAt,\n      orderedAtTz\n    )\n  }\n}\n\nobject CustomerOrderRow {\n  val `_rowParser`: RowParser[CustomerOrderRow] = RowParsers.of(CustomerOrderId.duckDbType, CustomerId.duckDbType, AddressId.duckDbType.nullable, AddressId.duckDbType.nullable, DuckDbTypes.varchar.nullable, ScalaDbTypes.DuckDbTypes.numeric, ScalaDbTypes.DuckDbTypes.numeric.nullable, ScalaDbTypes.DuckDbTypes.numeric.nullable, ScalaDbTypes.DuckDbTypes.numeric, DuckDbTypes.varchar.nullable, DuckDbTypes.timestamp.nullable, DuckDbTypes.timestamp.nullable, DuckDbTypes.timestamp.nullable, DuckDbTypes.timestamptz.nullable, DuckDbTypes.timestamptz.nullable, DuckDbTypes.varchar.array().nullable, DuckDbTypes.timestamp.array().nullable, CustomerOrderLineItemsSummary.duckDbType.nullable, DuckDbTypes.varchar.mapTo(DuckDbTypes.varchar).nullable, DuckDbTypes.interval.nullable)(CustomerOrderRow.apply)(row => Array[Any](row.id, row.customerId, row.shippingAddressId, row.billingAddressId, row.status, row.subtotal, row.tax, row.shipping, row.total, row.notes, row.createdAt, row.shippedAt, row.deliveredAt, row.orderedAtTz, row.deliveredAtTz, row.tags, row.fulfillmentTimes, row.lineItemsSummary, row.metadata, row.processingTime))\n}",
