      "OrderItemRow": "package showcase.showcase.order_item\n\nimport dev.typr.foundations.scala.DbTypeOps\nimport dev.typr.foundations.scala.RowParser\nimport dev.typr.foundations.scala.RowParsers\nimport dev.typr.foundations.scala.ScalaDbTypes\nimport showcase.customtypes.Defaulted\nimport showcase.showcase.customer_order.CustomerOrderId\nimport showcase.showcase.product.ProductId\n\n/** Table: showcase.order_item\n * Composite primary key: order_id, product_id\n */\ncase class OrderItemRow(\n  /** Points to [[showcase.showcase.customer_order.CustomerOrderRow.id]] */\n  orderId: CustomerOrderId,\n  /** Points to [[showcase.showcase.product.ProductRow.id]] */\n  productId: ProductId,\n  quantity: Int,\n  unitPrice: BigDecimal,\n  /** Default: 0 */\n  discount: Option[BigDecimal]\n) {\n  def compositeId: OrderItemId = new OrderItemId(orderId, productId)\n\n  def id: OrderItemId = this.compositeId\n\n  def toUnsavedRow(discount: Defaulted[Option[BigDecimal]] = Defaulted.Provided(this.discount)): OrderItemRowUnsaved = {\n    new OrderItemRowUnsaved(\n      orderId,\n      productId,\n      quantity,\n      unitPrice,\n      discount\n    )\n  }\n}\n\nobject OrderItemRow {\n  val `_rowParser`: RowParser[OrderItemRow] = RowParsers.of(CustomerOrderId.duckDbType, ProductId.duckDbType, ScalaDbTypes.DuckDbTypes.integer, ScalaDbTypes.DuckDbTypes.numeric, ScalaDbTypes.DuckDbTypes.numeric.nullable)(OrderItemRow.apply)(row => Array[Any](row.orderId, row.productId, row.quantity, row.unitPrice, row.discount))\n\n  def apply(\n    compositeId: OrderItemId,\n    quantity: Int,\n    unitPrice: BigDecimal,\n    discount: Option[BigDecimal]\n  ): OrderItemRow = {\n    new OrderItemRow(\n      compositeId.orderId,\n      compositeId.productId,\n      quantity,\n      unitPrice,\n      discount\n    )\n  }\n}",
