      "CompanyRepo": "package showcase.showcase.company\n\nimport dev.typr.foundations.kotlin.DeleteBuilder\nimport dev.typr.foundations.kotlin.SelectBuilder\nimport dev.typr.foundations.kotlin.UpdateBuilder\nimport java.sql.Connection\nimport kotlin.collections.Iterator\nimport kotlin.collections.List\nimport kotlin.collections.Map\n\ninterface CompanyRepo {\n  abstract fun delete(): DeleteBuilder<CompanyFields, CompanyRow>\n\n  abstract fun deleteById(\n    id: CompanyId,\n    c: Connection\n  ): Boolean\n\n  abstract fun deleteByIds(\n    ids: Array<CompanyId>,\n    c: Connection\n  ): Int\n\n  abstract fun insert(\n    unsaved: CompanyRow,\n    c: Connection\n  ): CompanyRow\n\n  abstract fun insert(\n    unsaved: CompanyRowUnsaved,\n    c: Connection\n  ): CompanyRow\n\n  abstract fun select(): SelectBuilder<CompanyFields, CompanyRow>\n\n  abstract fun selectAll(c: Connection): List<CompanyRow>\n\n  abstract fun selectById(\n    id: CompanyId,\n    c: Connection\n  ): CompanyRow?\n\n  abstract fun selectByIds(\n    ids: Array<CompanyId>,\n    c: Connection\n  ): List<CompanyRow>\n\n  abstract fun selectByIdsTracked(\n    ids: Array<CompanyId>,\n    c: Connection\n  ): Map<CompanyId, CompanyRow>\n\n  abstract fun update(): UpdateBuilder<CompanyFields, CompanyRow>\n\n  abstract fun update(\n    row: CompanyRow,\n    c: Connection\n  ): Boolean\n\n  abstract fun upsert(\n    unsaved: CompanyRow,\n    c: Connection\n  ): CompanyRow\n\n  abstract fun upsertBatch(\n    unsaved: Iterator<CompanyRow>,\n    c: Connection\n  ): List<CompanyRow>\n}",
      "CompanyRepoMock": "package showcase.showcase.company\n\nimport dev.typr.foundations.kotlin.DeleteBuilder\nimport dev.typr.foundations.kotlin.DeleteBuilderMock\nimport dev.typr.foundations.kotlin.DeleteParams\nimport dev.typr.foundations.kotlin.SelectBuilder\nimport dev.typr.foundations.kotlin.SelectBuilderMock\nimport dev.typr.foundations.kotlin.SelectParams\nimport dev.typr.foundations.kotlin.UpdateBuilder\nimport dev.typr.foundations.kotlin.UpdateBuilderMock\nimport dev.typr.foundations.kotlin.UpdateParams\nimport java.lang.RuntimeException\nimport java.sql.Connection\nimport java.util.ArrayList\nimport kotlin.collections.Iterator\nimport kotlin.collections.List\nimport kotlin.collections.Map\nimport kotlin.collections.MutableMap\n\ndata class CompanyRepoMock(\n  val toRow: (CompanyRowUnsaved) -> CompanyRow,\n  val map: MutableMap<CompanyId, CompanyRow> = mutableMapOf<CompanyId, CompanyRow>()\n) : CompanyRepo {\n  override fun delete(): DeleteBuilder<CompanyFields, CompanyRow> = DeleteBuilderMock(CompanyFields.structure, { map.values.toList() }, DeleteParams.empty(), { row -> row.id }, { id -> map.remove(id) })\n\n  override fun deleteById(\n    id: CompanyId,\n    c: Connection\n  ): Boolean = map.remove(id) != null\n\n  override fun deleteByIds(\n    ids: Array<CompanyId>,\n    c: Connection\n  ): Int {\n    var count = 0\n    for (id in ids) {\n      if (map.remove(id) != null) {\n      count = count + 1\n    }\n    }\n    return count\n  }\n\n  override fun insert(\n    unsaved: CompanyRow,\n    c: Connection\n  ): CompanyRow {\n    if (map.containsKey(unsaved.id)) {\n      throw RuntimeException(\"id \" + unsaved.id + \" already exists\")\n    }\n    map[unsaved.id] = unsaved\n    return unsaved\n  }\n\n  override fun insert(\n    unsaved: CompanyRowUnsaved,\n    c: Connection\n  ): CompanyRow = insert(toRow(unsaved), c)\n\n  override fun select(): SelectBuilder<CompanyFields, CompanyRow> = SelectBuilderMock(CompanyFields.structure, { map.values.toList() }, SelectParams.empty())\n\n  override fun selectAll(c: Connection): List<CompanyRow> = map.values.toList()\n\n  override fun selectById(\n    id: CompanyId,\n    c: Connection\n  ): CompanyRow? = map[id]\n\n  override fun selectByIds(\n    ids: Array<CompanyId>,\n    c: Connection\n  ): List<CompanyRow> {\n    val result = ArrayList<CompanyRow>()\n    for (id in ids) {\n      val opt = map[id]\n      if (opt != null) {\n      result.add(opt!!)\n    }\n    }\n    return result\n  }\n\n  override fun selectByIdsTracked(\n    ids: Array<CompanyId>,\n    c: Connection\n  ): Map<CompanyId, CompanyRow> = selectByIds(ids, c).associateBy({ row: CompanyRow -> row.id })\n\n  override fun update(): UpdateBuilder<CompanyFields, CompanyRow> = UpdateBuilderMock(CompanyFields.structure, { map.values.toList() }, UpdateParams.empty(), { row -> row })\n\n  override fun update(\n    row: CompanyRow,\n    c: Connection\n  ): Boolean {\n    val shouldUpdate = map[row.id]?.takeIf({ oldRow -> (oldRow != row) }) != null\n    if (shouldUpdate) {\n      map[row.id] = row\n    }\n    return shouldUpdate\n  }\n\n  override fun upsert(\n    unsaved: CompanyRow,\n    c: Connection\n  ): CompanyRow {\n    map[unsaved.id] = unsaved\n    return unsaved\n  }\n\n  override fun upsertBatch(\n    unsaved: Iterator<CompanyRow>,\n    c: Connection\n  ): List<CompanyRow> {\n    val result = ArrayList<CompanyRow>()\n    while (unsaved.hasNext()) {\n      val row = unsaved.next()\n      map[row.id] = row\n      result.add(row)\n    }\n    return result\n  }\n}",
