      "CompanyRow": "package showcase.showcase.company\n\nimport dev.typr.foundations.OracleTypes\nimport dev.typr.foundations.scala.DbTypeOps\nimport dev.typr.foundations.scala.RowParser\nimport dev.typr.foundations.scala.RowParsers\nimport dev.typr.foundations.scala.ScalaDbTypes\nimport java.time.LocalDateTime\nimport showcase.customtypes.Defaulted\n\n/** Table: showcase.company\n * Primary key: id\n */\ncase class CompanyRow(\n  id: CompanyId,\n  name: String,\n  foundedYear: Option[BigDecimal],\n  /** Default: true */\n  active: Option[BigDecimal],\n  /** Default: CURRENT_TIMESTAMP */\n  createdAt: Option[LocalDateTime]\n) {\n  def toUnsavedRow(\n    active: Defaulted[Option[BigDecimal]] = Defaulted.Provided(this.active),\n    createdAt: Defaulted[Option[LocalDateTime]] = Defaulted.Provided(this.createdAt)\n  ): CompanyRowUnsaved = {\n    new CompanyRowUnsaved(\n      id,\n      name,\n      foundedYear,\n      active,\n      createdAt\n    )\n  }\n}\n\nobject CompanyRow {\n  val `_rowParser`: RowParser[CompanyRow] = RowParsers.of(CompanyId.oracleType, OracleTypes.varchar2, ScalaDbTypes.OracleTypes.number.nullable, ScalaDbTypes.OracleTypes.number.nullable, OracleTypes.timestamp.nullable)(CompanyRow.apply)(row => Array[Any](row.id, row.name, row.foundedYear, row.active, row.createdAt))\n}",
      "CompanyRowUnsaved": "package showcase.showcase.company\n\nimport java.time.LocalDateTime\nimport showcase.customtypes.Defaulted\nimport showcase.customtypes.Defaulted.UseDefault\n\n/** This class corresponds to a row in table `showcase.company` which has not been persisted yet */\ncase class CompanyRowUnsaved(\n  id: CompanyId,\n  name: String,\n  foundedYear: Option[BigDecimal] = None,\n  /** Default: true */\n  active: Defaulted[Option[BigDecimal]] = new UseDefault(),\n  /** Default: CURRENT_TIMESTAMP */\n  createdAt: Defaulted[Option[LocalDateTime]] = new UseDefault()\n) {\n  def toRow(\n    activeDefault: => Option[BigDecimal],\n    createdAtDefault: => Option[LocalDateTime]\n  ): CompanyRow = {\n    new CompanyRow(\n      id = id,\n      name = name,\n      foundedYear = foundedYear,\n      active = active.getOrElse(activeDefault),\n      createdAt = createdAt.getOrElse(createdAtDefault)\n    )\n  }\n}",
