      "CompanyRepo": "package showcase.showcase.company\n\nimport dev.typr.foundations.scala.DeleteBuilder\nimport dev.typr.foundations.scala.SelectBuilder\nimport dev.typr.foundations.scala.UpdateBuilder\nimport java.sql.Connection\n\ntrait CompanyRepo {\n  def delete: DeleteBuilder[CompanyFields, CompanyRow]\n\n  def deleteById(id: CompanyId)(using c: Connection): Boolean\n\n  def deleteByIds(ids: Array[CompanyId])(using c: Connection): Int\n\n  def insert(unsaved: CompanyRow)(using c: Connection): CompanyRow\n\n  def insert(unsaved: CompanyRowUnsaved)(using c: Connection): CompanyRow\n\n  def select: SelectBuilder[CompanyFields, CompanyRow]\n\n  def selectAll(using c: Connection): List[CompanyRow]\n\n  def selectById(id: CompanyId)(using c: Connection): Option[CompanyRow]\n\n  def selectByIds(ids: Array[CompanyId])(using c: Connection): List[CompanyRow]\n\n  def selectByIdsTracked(ids: Array[CompanyId])(using c: Connection): Map[CompanyId, CompanyRow]\n\n  def update: UpdateBuilder[CompanyFields, CompanyRow]\n\n  def update(row: CompanyRow)(using c: Connection): Boolean\n\n  def upsert(unsaved: CompanyRow)(using c: Connection): CompanyRow\n\n  def upsertBatch(unsaved: Iterator[CompanyRow])(using c: Connection): List[CompanyRow]\n}",
      "CompanyRepoMock": "package showcase.showcase.company\n\nimport dev.typr.foundations.scala.DeleteBuilder\nimport dev.typr.foundations.scala.DeleteBuilderMock\nimport dev.typr.foundations.scala.DeleteParams\nimport dev.typr.foundations.scala.SelectBuilder\nimport dev.typr.foundations.scala.SelectBuilderMock\nimport dev.typr.foundations.scala.SelectParams\nimport dev.typr.foundations.scala.UpdateBuilder\nimport dev.typr.foundations.scala.UpdateBuilderMock\nimport dev.typr.foundations.scala.UpdateParams\nimport java.lang.RuntimeException\nimport java.sql.Connection\n\ncase class CompanyRepoMock(\n  toRow: CompanyRowUnsaved => CompanyRow,\n  map: scala.collection.mutable.Map[CompanyId, CompanyRow] = scala.collection.mutable.Map.empty[CompanyId, CompanyRow]\n) extends CompanyRepo {\n  override def delete: DeleteBuilder[CompanyFields, CompanyRow] = DeleteBuilderMock(CompanyFields.structure, () => map.values.toList, DeleteParams.empty(), row => row.id, id => map.remove(id): @scala.annotation.nowarn)\n\n  override def deleteById(id: CompanyId)(using c: Connection): Boolean = map.remove(id).isDefined\n\n  override def deleteByIds(ids: Array[CompanyId])(using c: Connection): Int = {\n    var count = 0\n    ids.foreach { id => if (map.remove(id).isDefined) {\n      count = count + 1\n    } }\n    return count\n  }\n\n  override def insert(unsaved: CompanyRow)(using c: Connection): CompanyRow = {\n    if (map.contains(unsaved.id)) {\n      throw new RuntimeException(s\"id ${unsaved.id} already exists\")\n    }\n    map.put(unsaved.id, unsaved): @scala.annotation.nowarn\n    return unsaved\n  }\n\n  override def insert(unsaved: CompanyRowUnsaved)(using c: Connection): CompanyRow = insert(toRow(unsaved))(using c)\n\n  override def select: SelectBuilder[CompanyFields, CompanyRow] = SelectBuilderMock(CompanyFields.structure, () => map.values.toList, SelectParams.empty())\n\n  override def selectAll(using c: Connection): List[CompanyRow] = map.values.toList\n\n  override def selectById(id: CompanyId)(using c: Connection): Option[CompanyRow] = map.get(id)\n\n  override def selectByIds(ids: Array[CompanyId])(using c: Connection): List[CompanyRow] = ids.flatMap(map.get(_)).toList\n\n  override def selectByIdsTracked(ids: Array[CompanyId])(using c: Connection): Map[CompanyId, CompanyRow] = selectByIds(ids)(using c).map(x => (((row: CompanyRow) => row.id).apply(x), x)).toMap\n\n  override def update: UpdateBuilder[CompanyFields, CompanyRow] = UpdateBuilderMock(CompanyFields.structure, () => map.values.toList, UpdateParams.empty(), row => row)\n\n  override def update(row: CompanyRow)(using c: Connection): Boolean = {\n    val shouldUpdate = map.get(row.id).filter(oldRow => (oldRow != row)).isDefined\n    if (shouldUpdate) {\n      map.put(row.id, row): @scala.annotation.nowarn\n    }\n    return shouldUpdate\n  }\n\n  override def upsert(unsaved: CompanyRow)(using c: Connection): CompanyRow = {\n    map.put(unsaved.id, unsaved): @scala.annotation.nowarn\n    return unsaved\n  }\n\n  override def upsertBatch(unsaved: Iterator[CompanyRow])(using c: Connection): List[CompanyRow] = {\n    unsaved.map { row =>\n      map.put(row.id, row): @scala.annotation.nowarn\n      row\n    }.toList\n  }\n}",
