      "DepartmentRow": "package showcase.showcase.department\n\nimport dev.typr.foundations.OracleTypes\nimport dev.typr.foundations.scala.DbTypeOps\nimport dev.typr.foundations.scala.RowParser\nimport dev.typr.foundations.scala.RowParsers\nimport dev.typr.foundations.scala.ScalaDbTypes\nimport showcase.showcase.company.CompanyId\n\n/** Table: showcase.department\n * Primary key: id\n */\ncase class DepartmentRow(\n  id: DepartmentId,\n  /** Points to [[showcase.showcase.company.CompanyRow.id]] */\n  companyId: CompanyId,\n  name: String,\n  budget: Option[BigDecimal]\n)\n\nobject DepartmentRow {\n  val `_rowParser`: RowParser[DepartmentRow] = RowParsers.of(DepartmentId.oracleType, CompanyId.oracleType, OracleTypes.varchar2, ScalaDbTypes.OracleTypes.number.nullable)(DepartmentRow.apply)(row => Array[Any](row.id, row.companyId, row.name, row.budget))\n}",
      "DepartmentId": "package showcase.showcase.department\n\nimport dev.typr.foundations.OracleType\nimport dev.typr.foundations.OracleTypes\nimport dev.typr.foundations.scala.Bijection\nimport dev.typr.foundations.scala.RowParser\nimport dev.typr.foundations.scala.RowParsers\n\n/** Type for the primary key of table `showcase.department` */\ncase class DepartmentId(value: String) extends scala.AnyVal\n\nobject DepartmentId {\n  given `_rowParser`: RowParser[DepartmentId] = RowParsers.of(OracleTypes.varchar2.bimap(DepartmentId.apply, _.value))(x => x)(id => Array[Any](id))\n\n  given bijection: Bijection[DepartmentId, String] = Bijection.apply[DepartmentId, String](_.value)(DepartmentId.apply)\n\n  given oracleType: OracleType[DepartmentId] = OracleTypes.varchar2.bimap(DepartmentId.apply, _.value)\n}",
      "DepartmentRepo": "package showcase.showcase.department\n\nimport dev.typr.foundations.scala.DeleteBuilder\nimport dev.typr.foundations.scala.SelectBuilder\nimport dev.typr.foundations.scala.UpdateBuilder\nimport java.sql.Connection\n\ntrait DepartmentRepo {\n  def delete: DeleteBuilder[DepartmentFields, DepartmentRow]\n\n  def deleteById(id: DepartmentId)(using c: Connection): Boolean\n\n  def deleteByIds(ids: Array[DepartmentId])(using c: Connection): Int\n\n  def insert(unsaved: DepartmentRow)(using c: Connection): DepartmentRow\n\n  def select: SelectBuilder[DepartmentFields, DepartmentRow]\n\n  def selectAll(using c: Connection): List[DepartmentRow]\n\n  def selectById(id: DepartmentId)(using c: Connection): Option[DepartmentRow]\n\n  def selectByIds(ids: Array[DepartmentId])(using c: Connection): List[DepartmentRow]\n\n  def selectByIdsTracked(ids: Array[DepartmentId])(using c: Connection): Map[DepartmentId, DepartmentRow]\n\n  def update: UpdateBuilder[DepartmentFields, DepartmentRow]\n\n  def update(row: DepartmentRow)(using c: Connection): Boolean\n\n  def upsert(unsaved: DepartmentRow)(using c: Connection): DepartmentRow\n\n  def upsertBatch(unsaved: Iterator[DepartmentRow])(using c: Connection): List[DepartmentRow]\n}",
      "DepartmentRepoMock": "package showcase.showcase.department\n\nimport dev.typr.foundations.scala.DeleteBuilder\nimport dev.typr.foundations.scala.DeleteBuilderMock\nimport dev.typr.foundations.scala.DeleteParams\nimport dev.typr.foundations.scala.SelectBuilder\nimport dev.typr.foundations.scala.SelectBuilderMock\nimport dev.typr.foundations.scala.SelectParams\nimport dev.typr.foundations.scala.UpdateBuilder\nimport dev.typr.foundations.scala.UpdateBuilderMock\nimport dev.typr.foundations.scala.UpdateParams\nimport java.lang.RuntimeException\nimport java.sql.Connection\n\ncase class DepartmentRepoMock(map: scala.collection.mutable.Map[DepartmentId, DepartmentRow] = scala.collection.mutable.Map.empty[DepartmentId, DepartmentRow]) extends DepartmentRepo {\n  override def delete: DeleteBuilder[DepartmentFields, DepartmentRow] = DeleteBuilderMock(DepartmentFields.structure, () => map.values.toList, DeleteParams.empty(), row => row.id, id => map.remove(id): @scala.annotation.nowarn)\n\n  override def deleteById(id: DepartmentId)(using c: Connection): Boolean = map.remove(id).isDefined\n\n  override def deleteByIds(ids: Array[DepartmentId])(using c: Connection): Int = {\n    var count = 0\n    ids.foreach { id => if (map.remove(id).isDefined) {\n      count = count + 1\n    } }\n    return count\n  }\n\n  override def insert(unsaved: DepartmentRow)(using c: Connection): DepartmentRow = {\n    if (map.contains(unsaved.id)) {\n      throw new RuntimeException(s\"id ${unsaved.id} already exists\")\n    }\n    map.put(unsaved.id, unsaved): @scala.annotation.nowarn\n    return unsaved\n  }\n\n  override def select: SelectBuilder[DepartmentFields, DepartmentRow] = SelectBuilderMock(DepartmentFields.structure, () => map.values.toList, SelectParams.empty())\n\n  override def selectAll(using c: Connection): List[DepartmentRow] = map.values.toList\n\n  override def selectById(id: DepartmentId)(using c: Connection): Option[DepartmentRow] = map.get(id)\n\n  override def selectByIds(ids: Array[DepartmentId])(using c: Connection): List[DepartmentRow] = ids.flatMap(map.get(_)).toList\n\n  override def selectByIdsTracked(ids: Array[DepartmentId])(using c: Connection): Map[DepartmentId, DepartmentRow] = selectByIds(ids)(using c).map(x => (((row: DepartmentRow) => row.id).apply(x), x)).toMap\n\n  override def update: UpdateBuilder[DepartmentFields, DepartmentRow] = UpdateBuilderMock(DepartmentFields.structure, () => map.values.toList, UpdateParams.empty(), row => row)\n\n  override def update(row: DepartmentRow)(using c: Connection): Boolean = {\n    val shouldUpdate = map.get(row.id).filter(oldRow => (oldRow != row)).isDefined\n    if (shouldUpdate) {\n      map.put(row.id, row): @scala.annotation.nowarn\n    }\n    return shouldUpdate\n  }\n\n  override def upsert(unsaved: DepartmentRow)(using c: Connection): DepartmentRow = {\n    map.put(unsaved.id, unsaved): @scala.annotation.nowarn\n    return unsaved\n  }\n\n  override def upsertBatch(unsaved: Iterator[DepartmentRow])(using c: Connection): List[DepartmentRow] = {\n    unsaved.map { row =>\n      map.put(row.id, row): @scala.annotation.nowarn\n      row\n    }.toList\n  }\n}",
