      "DepartmentId": "package showcase.showcase.department\n\nimport dev.typr.foundations.SqlServerType\nimport dev.typr.foundations.SqlServerTypes\nimport dev.typr.foundations.kotlin.Bijection\n\n/** Type for the primary key of table `showcase.department` */\ndata class DepartmentId(val value: String) {\n  override fun toString(): kotlin.String {\n    return value.toString()\n  }\n\n  companion object {\n    val bijection: Bijection<DepartmentId, String> =\n      Bijection.of(DepartmentId::value, ::DepartmentId)\n\n    val sqlServerType: SqlServerType<DepartmentId> =\n      SqlServerTypes.nvarchar.bimap(::DepartmentId, DepartmentId::value)\n  }\n}",
