      "ProductRow": "package showcase.showcase.product\n\nimport dev.typr.foundations.SqlServerTypes\nimport dev.typr.foundations.data.Json\nimport dev.typr.foundations.kotlin.KotlinDbTypes\nimport dev.typr.foundations.kotlin.RowParser\nimport dev.typr.foundations.kotlin.RowParsers\nimport dev.typr.foundations.kotlin.nullable\nimport java.math.BigDecimal\nimport java.time.LocalDateTime\nimport java.util.UUID\nimport showcase.customtypes.Defaulted\nimport showcase.showcase.category.CategoryId\n\n/** Table: showcase.product\n  * Primary key: id\n  */\ndata class ProductRow(\n  val id: ProductId,\n  /** Points to [showcase.showcase.category.CategoryRow.id] */\n  val categoryId: CategoryId?,\n  val name: String,\n  val sku: String,\n  val price: BigDecimal,\n  val cost: BigDecimal?,\n  /** Default: true */\n  val inStock: Boolean?,\n  /** Default: 0 */\n  val quantity: Int?,\n  val weight: BigDecimal?,\n  /** Default: CURRENT_TIMESTAMP */\n  val createdAt: LocalDateTime?,\n  val attributes: Json?,\n  val specifications: /* XML */ String?,\n  val descriptionLong: String?,\n  val thumbnail: ByteArray?,\n  val productUid: UUID?,\n  val listPrice: BigDecimal?\n) {\n  fun toUnsavedRow(\n    inStock: Defaulted<Boolean?>,\n    quantity: Defaulted<Int?>,\n    createdAt: Defaulted<LocalDateTime?>\n  ): ProductRowUnsaved = ProductRowUnsaved(id, categoryId, name, sku, price, cost, weight, attributes, specifications, descriptionLong, thumbnail, productUid, listPrice, inStock, quantity, createdAt)\n\n  companion object {\n    val _rowParser: RowParser<ProductRow> = RowParsers.of(ProductId.sqlServerType, CategoryId.sqlServerType.nullable(), SqlServerTypes.nvarchar, SqlServerTypes.nvarchar, KotlinDbTypes.SqlServerTypes.decimal, KotlinDbTypes.SqlServerTypes.decimal.nullable(), KotlinDbTypes.SqlServerTypes.bit.nullable(), KotlinDbTypes.SqlServerTypes.int_.nullable(), KotlinDbTypes.SqlServerTypes.decimal.nullable(), SqlServerTypes.datetime2.nullable(), SqlServerTypes.json.nullable(), SqlServerTypes.xml.nullable(), SqlServerTypes.nvarchar.nullable(), SqlServerTypes.varbinary.nullable(), SqlServerTypes.uniqueidentifier.nullable(), KotlinDbTypes.SqlServerTypes.money.nullable(), { t0, t1, t2, t3, t4, t5, t6, t7, t8, t9, t10, t11, t12, t13, t14, t15 -> ProductRow(t0, t1, t2, t3, t4, t5, t6, t7, t8, t9, t10, t11, t12, t13, t14, t15) }, { row -> arrayOf<Any?>(row.id, row.categoryId, row.name, row.sku, row.price, row.cost, row.inStock, row.quantity, row.weight, row.createdAt, row.attributes, row.specifications, row.descriptionLong, row.thumbnail, row.productUid, row.listPrice) })\n  }\n}",
      "ProductId": "package showcase.showcase.product\n\nimport dev.typr.foundations.SqlServerType\nimport dev.typr.foundations.SqlServerTypes\nimport dev.typr.foundations.kotlin.Bijection\n\n/** Type for the primary key of table `showcase.product` */\ndata class ProductId(val value: String) {\n  override fun toString(): kotlin.String {\n    return value.toString()\n  }\n\n  companion object {\n    val bijection: Bijection<ProductId, String> =\n      Bijection.of(ProductId::value, ::ProductId)\n\n    val sqlServerType: SqlServerType<ProductId> =\n      SqlServerTypes.nvarchar.bimap(::ProductId, ProductId::value)\n  }\n}",
