      "AddressRow": "package showcase.showcase.address\n\nimport com.microsoft.sqlserver.jdbc.Geography\nimport com.microsoft.sqlserver.jdbc.Geometry\nimport dev.typr.foundations.SqlServerTypes\nimport dev.typr.foundations.kotlin.KotlinDbTypes\nimport dev.typr.foundations.kotlin.RowParser\nimport dev.typr.foundations.kotlin.RowParsers\nimport dev.typr.foundations.kotlin.nullable\nimport showcase.customtypes.Defaulted\nimport showcase.showcase.customer.CustomerId\n\n/** Table: showcase.address\n  * Primary key: id\n  */\ndata class AddressRow(\n  val id: AddressId,\n  /** Points to [showcase.showcase.customer.CustomerRow.id] */\n  val customerId: CustomerId,\n  val addressType: String,\n  val street: String,\n  val city: String,\n  val state: String?,\n  val postalCode: String?,\n  val country: String,\n  /** Default: false */\n  val isDefault: Boolean?,\n  val location: Geography?,\n  val deliveryZone: Geometry?\n) {\n  fun toUnsavedRow(isDefault: Defaulted<Boolean?>): AddressRowUnsaved = AddressRowUnsaved(id, customerId, addressType, street, city, state, postalCode, country, location, deliveryZone, isDefault)\n\n  companion object {\n    val _rowParser: RowParser<AddressRow> = RowParsers.of(AddressId.sqlServerType, CustomerId.sqlServerType, SqlServerTypes.nvarchar, SqlServerTypes.nvarchar, SqlServerTypes.nvarchar, SqlServerTypes.nvarchar.nullable(), SqlServerTypes.nvarchar.nullable(), SqlServerTypes.nvarchar, KotlinDbTypes.SqlServerTypes.bit.nullable(), SqlServerTypes.geography.nullable(), SqlServerTypes.geometry.nullable(), { t0, t1, t2, t3, t4, t5, t6, t7, t8, t9, t10 -> AddressRow(t0, t1, t2, t3, t4, t5, t6, t7, t8, t9, t10) }, { row -> arrayOf<Any?>(row.id, row.customerId, row.addressType, row.street, row.city, row.state, row.postalCode, row.country, row.isDefault, row.location, row.deliveryZone) })\n  }\n}",
      "AddressId": "package showcase.showcase.address\n\nimport dev.typr.foundations.SqlServerType\nimport dev.typr.foundations.SqlServerTypes\nimport dev.typr.foundations.kotlin.Bijection\n\n/** Type for the primary key of table `showcase.address` */\ndata class AddressId(val value: String) {\n  override fun toString(): kotlin.String {\n    return value.toString()\n  }\n\n  companion object {\n    val bijection: Bijection<AddressId, String> =\n      Bijection.of(AddressId::value, ::AddressId)\n\n    val sqlServerType: SqlServerType<AddressId> =\n      SqlServerTypes.nvarchar.bimap(::AddressId, AddressId::value)\n  }\n}",
      "Defaulted": "package showcase.customtypes\n\n\n\n/** This signals a value where if you don't provide it, postgres will generate it for you */\nsealed interface Defaulted<T> {\n  data class Provided<T>(val value: T) : Defaulted<T> {\n    override fun <U>fold(\n      onDefault: () -> U,\n      onProvided: (T) -> U\n    ): U = onProvided(value)\n\n    override fun getOrElse(onDefault: () -> T): T = value\n\n    override fun visit(\n      onDefault: () -> Unit,\n      onProvided: (T) -> Unit\n    ) {\n      onProvided(value)\n    }\n  }\n\n  class UseDefault<T> : Defaulted<T> {\n    override fun <U>fold(\n      onDefault: () -> U,\n      onProvided: (T) -> U\n    ): U = onDefault()\n\n    override fun getOrElse(onDefault: () -> T): T = onDefault()\n\n    override fun visit(\n      onDefault: () -> Unit,\n      onProvided: (T) -> Unit\n    ) {\n      onDefault()\n    }\n  }\n\n  abstract fun <U>fold(\n    onDefault: () -> U,\n    onProvided: (T) -> U\n  ): U\n\n  abstract fun getOrElse(onDefault: () -> T): T\n\n  abstract fun visit(\n    onDefault: () -> Unit,\n    onProvided: (T) -> Unit\n  )\n}",
