      "EmployeeRepoMock": "package showcase.showcase.employee\n\nimport dev.typr.foundations.scala.DeleteBuilder\nimport dev.typr.foundations.scala.DeleteBuilderMock\nimport dev.typr.foundations.scala.DeleteParams\nimport dev.typr.foundations.scala.SelectBuilder\nimport dev.typr.foundations.scala.SelectBuilderMock\nimport dev.typr.foundations.scala.SelectParams\nimport dev.typr.foundations.scala.UpdateBuilder\nimport dev.typr.foundations.scala.UpdateBuilderMock\nimport dev.typr.foundations.scala.UpdateParams\nimport java.lang.RuntimeException\nimport java.sql.Connection\n\ncase class EmployeeRepoMock(\n  toRow: EmployeeRowUnsaved => EmployeeRow,\n  map: scala.collection.mutable.Map[EmployeeId, EmployeeRow] = scala.collection.mutable.Map.empty[EmployeeId, EmployeeRow]\n) extends EmployeeRepo {\n  override def delete: DeleteBuilder[EmployeeFields, EmployeeRow] = DeleteBuilderMock(EmployeeFields.structure, () => map.values.toList, DeleteParams.empty(), row => row.id, id => map.remove(id): @scala.annotation.nowarn)\n\n  override def deleteById(id: EmployeeId)(using c: Connection): Boolean = map.remove(id).isDefined\n\n  override def deleteByIds(ids: Array[EmployeeId])(using c: Connection): Int = {\n    var count = 0\n    ids.foreach { id => if (map.remove(id).isDefined) {\n      count = count + 1\n    } }\n    return count\n  }\n\n  override def insert(unsaved: EmployeeRow)(using c: Connection): EmployeeRow = {\n    if (map.contains(unsaved.id)) {\n      throw new RuntimeException(s\"id ${unsaved.id} already exists\")\n    }\n    map.put(unsaved.id, unsaved): @scala.annotation.nowarn\n    return unsaved\n  }\n\n  override def insert(unsaved: EmployeeRowUnsaved)(using c: Connection): EmployeeRow = insert(toRow(unsaved))(using c)\n\n  override def select: SelectBuilder[EmployeeFields, EmployeeRow] = SelectBuilderMock(EmployeeFields.structure, () => map.values.toList, SelectParams.empty())\n\n  override def selectAll(using c: Connection): List[EmployeeRow] = map.values.toList\n\n  override def selectById(id: EmployeeId)(using c: Connection): Option[EmployeeRow] = map.get(id)\n\n  override def selectByIds(ids: Array[EmployeeId])(using c: Connection): List[EmployeeRow] = ids.flatMap(map.get(_)).toList\n\n  override def selectByIdsTracked(ids: Array[EmployeeId])(using c: Connection): Map[EmployeeId, EmployeeRow] = selectByIds(ids)(using c).map(x => (((row: EmployeeRow) => row.id).apply(x), x)).toMap\n\n  override def selectByUniqueEmail(email: String)(using c: Connection): Option[EmployeeRow] = map.values.toList.find(v => (email == v.email))\n\n  override def update: UpdateBuilder[EmployeeFields, EmployeeRow] = UpdateBuilderMock(EmployeeFields.structure, () => map.values.toList, UpdateParams.empty(), row => row)\n\n  override def update(row: EmployeeRow)(using c: Connection): Boolean = {\n    val shouldUpdate = map.get(row.id).filter(oldRow => (oldRow != row)).isDefined\n    if (shouldUpdate) {\n      map.put(row.id, row): @scala.annotation.nowarn\n    }\n    return shouldUpdate\n  }\n\n  override def upsert(unsaved: EmployeeRow)(using c: Connection): EmployeeRow = {\n    map.put(unsaved.id, unsaved): @scala.annotation.nowarn\n    return unsaved\n  }\n\n  override def upsertBatch(unsaved: Iterator[EmployeeRow])(using c: Connection): List[EmployeeRow] = {\n    unsaved.map { row =>\n      map.put(row.id, row): @scala.annotation.nowarn\n      row\n    }.toList\n  }\n}",
