/**
 * Get a code sample for the given database, language, and file name.
 * Returns null if the sample doesn't exist for that combination.
 */
export function getCodeSample(database, language, fileName) {
  return codeSamples[database]?.[language]?.[fileName] ?? null;
}

/**
 * Check if a code sample exists for the given combination.
 */
export function hasCodeSample(database, language, fileName) {
  return getCodeSample(database, language, fileName) !== null;
}

/**
 * Get all available samples for a file name across all database/language combinations.
 * Returns an object with { database: { language: content } } structure.
 */
export function getAllSamplesForFile(fileName) {
  const result = {};
  for (const db of DATABASES) {
    for (const lang of LANGUAGES) {
      const sample = getCodeSample(db, lang, fileName);
      if (sample) {
        if (!result[db]) result[db] = {};
        result[db][lang] = sample;
      }
    }
  }
  return result;
}
